/*
 * ONE CHECK-IN, AS ITS LEARNER SEES IT (DBU-10). Hers, shared and a check-in, or refused with the
 * same sentence whatever the reason, so the answer never says whose a step is.
 *   state 'waiting'   still to send: the page says when it opens (sendsAt; null if not dated yet)
 *   state 'open'      sent: the form to answer
 *   state 'answered'  done: the form she answered (the response's own copy) and her answers
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 2, plain: true });
    const id = String(Inputs.stepId || '');
    const steps = id ? await q('Step', { objectId: { equalTo: id } }) : [];
    const s = steps[0];
    if (!s || s.learner !== me || s.shared !== true || s.kind !== 'checkin') return refuse('This check-in could not be found. Open it from your Home page.');
    const responses = s.status === 'done' ? await q('CheckinResponse', { step: { equalTo: id } }) : [];
    const r = responses.find((x) => x.learner === me) || null;
    const users = await q('_User', { objectId: { equalTo: me } });
    const form = (r && r.form) || s.form || { questions: [] };
    Outputs.checkin = {
      id: s.objectId,
      title: s.title || '',
      state: r ? 'answered' : s.status === 'scheduled' ? 'waiting' : 'open',
      sendsAt: s.sendsAt || null,
      sentAt: s.sentAt || null,
      answeredAt: r ? r.createdAt : null,
      minutes: Number.isInteger(form.minutes) ? form.minutes : 2,
      questions: Array.isArray(form.questions) ? form.questions : [],
      answers: r ? r.answers || {} : null
    };
    Outputs.me = { timezone: (users[0] && users[0].timezone) || '' };
    Outputs.done();
  } catch (e) {
    console.error('[dbu:myCheckin]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
